-- 全库可见英文补全（第 2 批）：物品描述
-- By leewheel 2026年11月11日
--
-- 说明：本批处理 item_template.description 里仍是英文的条目，共三类：
--   ① 制造图样类「Teaches you how to ...」——按物品自身中文名模板化生成，
--      动词对应：craft/make/create=制作，sew=缝制，forge=锻造，cut=切割，
--      cook=烹饪，transmute=转化，summon=召唤，brew=酿造，其余按语义就近处理；
--   ② 技能卡固定说明——沿用库内既有中文译法，保持全服一致；
--   ③ 两条特殊配方手工翻译。
-- 不处理：以 @ 开头的协议串（如 @Refined@@Superior@ / @build:...@），
--         那是客户端与服务端等值比较用的标记，严禁本地化。
-- 只写 locale 表，不改 item_template 源表。

-- ① 制造图样 / 配方说明：697 条
